import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"合成队列","description":"","frontmatter":{},"headers":[],"relativePath":"modules/station/queue.md","filePath":"modules/station/queue.md","lastUpdated":0}`),a={name:`modules/station/queue.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="合成队列" tabindex="-1">合成队列 <a class="header-anchor" href="#合成队列" aria-label="Permalink to “合成队列”">​</a></h1><p>一个玩家在一个工作站拥有一条队列。队列是<strong>串行单线</strong>的：只有队首在推进，后面的条目排队等待。</p><h2 id="条目状态" tabindex="-1">条目状态 <a class="header-anchor" href="#条目状态" aria-label="Permalink to “条目状态”">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>是否占用队列长度</th><th>说明</th></tr></thead><tbody><tr><td><code>WAITING</code></td><td>是</td><td>已提交，排在队列中等待。</td></tr><tr><td><code>RUNNING</code></td><td>是</td><td>队首，正在推进耗时。</td></tr><tr><td><code>PENDING_CLAIM</code></td><td>否</td><td>已完成但产物没能投递，等待玩家领取。</td></tr></tbody></table><p><code>PENDING_CLAIM</code> 刻意不占用队列长度：否则仓库和背包同时满的玩家会被自己未投递的产物锁死队列，什么都排不进去。待领取条目由 <code>limits.max_pending_claim</code> 单独限制，默认 100。</p><h2 id="队列长度的三个来源" tabindex="-1">队列长度的三个来源 <a class="header-anchor" href="#队列长度的三个来源" aria-label="Permalink to “队列长度的三个来源”">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>与基础长度的关系</th><th>配置位置</th></tr></thead><tbody><tr><td>基础长度</td><td>起点</td><td><code>config.yml</code> 的 <code>queue.base_length</code>，工作站可覆盖。</td></tr><tr><td>权限档</td><td><strong>取代</strong></td><td><code>emakistation.queue.&lt;n&gt;</code>，需 <code>queue.permission_tiers: true</code>。</td></tr><tr><td>付费购买</td><td><strong>叠加</strong></td><td>队列页购买，见 <a href="./queue-costs.html">付费队列位</a>。</td></tr></tbody></table><p>权限档取数字最大的一档生效，没有任何该前缀权限时保持基础长度。付费额度叠加在生效档之上，最终统一被 <code>queue.max_length</code> 截断。</p><p>权限档是「取代」而付费是「叠加」，这样管理员事后给某个玩家发权限档，不会把他花钱买的额度吞掉。</p><h2 id="推进方式" tabindex="-1">推进方式 <a class="header-anchor" href="#推进方式" aria-label="Permalink to “推进方式”">​</a></h2><p><code>queue.progress_mode</code> 决定队首如何计时：</p><table tabindex="0"><thead><tr><th>值</th><th>行为</th></tr></thead><tbody><tr><td><code>offline</code></td><td>按真实时间推进，玩家离线期间继续走时。</td></tr><tr><td><code>online</code></td><td>仅在玩家在线时累计。</td></tr></tbody></table><p><code>offline</code> 只表示「计时继续」，不表示「离线发货」。EmakiStorage 拒绝对离线玩家做任何写操作，所以离线期间到点的条目只是「已到期」，真正结算发生在玩家下次上线时。</p><p>队列推进任务全服只有一个定时器，间隔由 <code>queue.tick_interval</code> 控制，默认 20 tick，不是每条队列一个定时器。</p><h2 id="耗时" tabindex="-1">耗时 <a class="header-anchor" href="#耗时" aria-label="Permalink to “耗时”">​</a></h2><p>单次耗时来自配方的 <code>duration_seconds</code>，再乘工作站或全局的 <code>speed_multiplier</code>。<code>duration_seconds</code> 为 <code>0</code> 或省略时立即完成，不进队列。</p><h2 id="取消与退还" tabindex="-1">取消与退还 <a class="header-anchor" href="#取消与退还" aria-label="Permalink to “取消与退还”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation cancel &lt;工作站&gt; &lt;序号&gt;</span></span></code></pre></div><p>命令与界面里的序号从 <strong>1</strong> 开始（API 的 <code>index</code> 参数从 0 开始）。</p><p>退还比例来自工作站的 <code>queue.cancel_refund_rate</code>，材料与已付货币按同一比例折算。退还<strong>总是回到材料原本来自的通道</strong>，与工作站的产物路由无关。</p><p>退还不按进度折算。串行单线队列里只有队首有进度，为一个几乎不存在的情况引入逐条目进度记账不值得，这是有意的简化。</p><p>部分退还仍然报告成功，缺口作为 <code>Partial</code> 原因键携带。</p><p><code>PENDING_CLAIM</code> 状态的条目不能取消，会被拒绝并返回 <code>station.cancel_pending_claim</code>。</p><h2 id="领取产物" tabindex="-1">领取产物 <a class="header-anchor" href="#领取产物" aria-label="Permalink to “领取产物”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation claim</span></span></code></pre></div><p>一次领取该玩家在<strong>所有工作站</strong>的全部可投递待领取产物。仍然投递不了的条目保持待领取而不是让整个调用失败，所以这个命令可以无条件执行。</p><h2 id="管理员操作" tabindex="-1">管理员操作 <a class="header-anchor" href="#管理员操作" aria-label="Permalink to “管理员操作”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/emakistation admin queue &lt;...&gt;</span></span></code></pre></div><p>需要 <code>emakistation.admin</code>。</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};